-- S5: 24 candidatas NUEVA y revisión C04 v2 (mapeo solo verificado parcialmente), 200 pruebas.
-- Sin publicación, juicio, cambios IG, lector, puente o legadas.
BEGIN;
DO $pre$ BEGIN
 IF (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='VIGENTE')<>105
  OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='CANDIDATA')<>13
  OR (SELECT count(*) FROM lf_ops.nucleo_deprecaciones)<>0
  OR (SELECT count(*) FROM lf_ops.reglas) NOT IN (215,586)
  OR (SELECT count(distinct legacy_id) FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA')<>86
  OR (SELECT hash FROM lf_ops.nucleo_regla_versiones WHERE regla='S4-C04' AND version=1)
       IS DISTINCT FROM 'ca6c604524be1dcc825a68248d1b5dbf0d6788569c0098f818ba130540b26c25'
 THEN RAISE EXCEPTION 'S5_BASELINE_DRIFT'; END IF;
END $pre$;
DO $rev$
DECLARE p jsonb:='{"tipo":"REVISION","codigo":"S4-C04","clave":"s4_estados_onb_canon","familia":"TRANSITIONS","naturaleza":"CONDUCTA","clase":"BACKEND","alcance":"BACKEND","modo":"HEREDA","dueno":"TECNICO","titulo":"Validar representación de estados onboarding contra persistencia comprobada","descripcion":"El catálogo funcional legado incluye INICIADO, PASO1_COMPLETO, OTP_ENVIADO, OTP_VERIFICADO, COMPLETADO, ABANDONADO, BLOQUEADO y EXPIRADO. La tabla real lf_client.onboarding_sessions no tiene columna de estado ni enum: dispone de created_at, otp_verified_at, completed_at, blocked_at y expires_at, que aportan evidencia para inicio, OTP verificado, completado, bloqueo y expiración por tiempo; lf_proto.proto_onboarding solo registra onboarding_step, otp_verified y onboarding_completed, no equivalencia canónica. PASO1_COMPLETO, OTP_ENVIADO y ABANDONADO carecen de correspondencia persistida unívoca verificada: BLOQUEAR proyección de cualquiera de estos estados como dato confirmado sin evento o política formal vinculada. No inventar códigos ni afirmar mapeo completo; documentar residual para decisión posterior.","condicion":{"op":"y","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"s4c04_intento"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s4c04_contexto"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s4c04_violacion"},"der":{"lit":true}}},"efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/34","solicitante":"Cristhian/Claude S5 revisión 2026-11-23"},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s4c04_intento":false,"s4c04_contexto":false,"s4c04_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s4c04_intento":false,"s4c04_contexto":false,"s4c04_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s4c04_intento":false,"s4c04_contexto":true,"s4c04_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s4c04_intento":false,"s4c04_contexto":true,"s4c04_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s4c04_intento":true,"s4c04_contexto":false,"s4c04_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s4c04_intento":true,"s4c04_contexto":false,"s4c04_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s4c04_intento":true,"s4c04_contexto":true,"s4c04_violacion":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s4c04_intento":true,"s4c04_contexto":true,"s4c04_violacion":true},"esperado":true}],"version_anterior":1,"hash_anterior":"ca6c604524be1dcc825a68248d1b5dbf0d6788569c0098f818ba130540b26c25","motivo_revision":"Juicio independiente DEVOLVER: reconciliar estados con esquema real lf_client.onboarding_sessions y lf_proto.proto_onboarding, sin inventar columna enum ni equivalencias no certificadas","mapping_evidence":{"fuente_principal":"lf_client.onboarding_sessions (columnas verificadas por information_schema)","campos_comprobados":["created_at","otp_verified_at","completed_at","blocked_at","expires_at"],"fuente_prototipo":"lf_proto.proto_onboarding","campos_prototipo":["onboarding_step","otp_verified","onboarding_completed"],"no_mapeados":["PASO1_COMPLETO","OTP_ENVIADO","ABANDONADO"],"nota":"No existe estado ni enum de onboarding en lf_client.onboarding_sessions; equivalencias requieren binding de runtime y nueva evidencia"}}'::jsonb; result jsonb; ev jsonb; oldhash text;
BEGIN
 oldhash:=(SELECT hash FROM lf_ops.nucleo_regla_versiones WHERE regla='S4-C04' AND version=1 AND estado='CANDIDATA');
 IF oldhash IS NULL THEN RAISE EXCEPTION 'S5_C04_V1_NOT_CANDIDATE'; END IF;
 result:=lf_ops.nucleo_regla_proponer_v1(p||jsonb_build_object('hash_anterior',repeat('0',64)),false);
 IF result->>'resultado'<>'RECHAZADA' OR (result->>'bloqueantes')::int<1
 THEN RAISE EXCEPTION 'S5_REVISION_BAD_HASH_ACCEPTED: %',result; END IF;
 result:=lf_ops.nucleo_regla_proponer_v1(p,false);
 IF result->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (result->>'bloqueantes')::int<>0
 THEN RAISE EXCEPTION 'S5_C04_PREFLIGHT %',result; END IF;
 result:=lf_ops.nucleo_regla_proponer_v1(p,true);
 IF result->>'resultado'<>'CANDIDATA' OR (result->>'version')::int<>2
 THEN RAISE EXCEPTION 'S5_C04_REVISION_FAILED %',result; END IF;
 IF (SELECT estado FROM lf_ops.nucleo_regla_versiones WHERE regla='S4-C04' AND version=1)<>'DESCARTADA'
 OR (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla='S4-C04' AND version=2)<>8
 THEN RAISE EXCEPTION 'S5_C04_VERSION_READBACK'; END IF;
 ev:=lf_ops.nucleo_regla_evaluar_v1('S4-C04',true);
 IF ev->>'decision'<>'BLOQUEADA' OR (ev->>'version')::int<>2
 THEN RAISE EXCEPTION 'S5_C04_MUST_BE_BLOCKED %',ev; END IF;
 RAISE NOTICE 'S5_C04_REVISION_PASS v2_blocked hash=%',ev->>'hash_paquete';
END $rev$;
DO $new$
DECLARE p jsonb; cd text; r jsonb; ev jsonb; n int:=0; legacy_before jsonb; bridge_before jsonb; dep_before jsonb;
BEGIN
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO legacy_before FROM lf_ops.reglas x;
