NO_SE_CUMPLE","entrada":{"s5c24_intento":true,"s5c24_contexto":false,"s5c24_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s5c24_intento":true,"s5c24_contexto":false,"s5c24_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s5c24_intento":true,"s5c24_contexto":true,"s5c24_violacion":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s5c24_intento":true,"s5c24_contexto":true,"s5c24_violacion":true},"esperado":true}]}]'::jsonb) LOOP
  cd:=p->>'codigo';
  r:=lf_ops.nucleo_regla_proponer_v1(p,false);
  IF r->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (r->>'bloqueantes')::int<>0
   THEN RAISE EXCEPTION 'S5_PREFLIGHT_REJECT % %',cd,r; END IF;
  r:=lf_ops.nucleo_regla_proponer_v1(p,true);
  IF r->>'resultado'<>'CANDIDATA' OR (r->>'version')::int<>1
   THEN RAISE EXCEPTION 'S5_CREATE_FAILED % %',cd,r; END IF;
  IF (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8
   OR (SELECT count(distinct entrada::text) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8
  THEN RAISE EXCEPTION 'S5_8_VECTORS_INVALID %',cd; END IF;
  ev:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
  IF ev->>'decision'<>'BLOQUEADA' THEN RAISE EXCEPTION 'S5_JUDGE_GATE_FAIL % %',cd,ev; END IF;
  n:=n+1;
  RAISE NOTICE 'S5_CANDIDATE % hash=%',cd,ev->>'hash_paquete';
 END LOOP;
 IF n<>24 OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='CANDIDATA')<>37
  OR (SELECT count(*) FROM lf_ops.nucleo_juicios WHERE regla LIKE 'S5-C%')<>0
  OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE regla LIKE 'S5-C%' AND estado='PUBLICADA')<>0
  OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM legacy_before
  OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY legacy_id,nucleo_codigo,version_nucleo) FROM lf_ops.lf_nucleo_cobertura_legada x) IS DISTINCT FROM bridge_before
  OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM dep_before
 THEN RAISE EXCEPTION 'S5_FINAL_INVALID'; END IF;
 RAISE NOTICE 'S5_PASS 24_NEW_CANDIDATES 192_VECTORS C04_REVISION_V2_8_VECTORS ALL_UNJUDGED';
END $new$;
COMMIT;
